def fib(n: int) -> int:
    """
    Returns the nth Fibonacci number using zero-based indexing.

    Args:
        n (int): The index of the Fibonacci number to return.

    Returns:
        int: The nth Fibonacci number.
    """

    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib(n-1) + fib(n-2)
